from functools import cmp_to_key

def _t():
    data = [(random.randrange(100), i) for i in range(200)]
    copy1 = data[:]
    copy2 = data[:]

    def my_cmp(x, y):
        x0, y0 = (x[0], y[0])
        return (x0 > y0) - (x0 < y0)

    def my_cmp_reversed(x, y):
        x0, y0 = (x[0], y[0])
        return (y0 > x0) - (y0 < x0)
    data.sort(key=cmp_to_key(my_cmp), reverse=True)
    copy1.sort(key=cmp_to_key(my_cmp_reversed))
    assert data == copy1, ('assertEqual', data, copy1)
    copy2.sort(key=lambda x: x[0], reverse=True)
    assert data == copy2, ('assertEqual', data, copy2)
try:
    _t()
except BaseException as _e:
    _oracle_write('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    _oracle_write('ok')

